using System;
using System.Drawing;
using System.Threading;
using System.Windows.Forms;
namespace Astera {
sealed class WorkMeter:Control {
    internal double Fraction=-1;
    public WorkMeter(){DoubleBuffered=true;Height=8;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Color.FromArgb(31,40,64));using(var brush=new SolidBrush(Fraction<0?Color.FromArgb(100,ButtonAtlas.AccentColor):ButtonAtlas.AccentColor)){if(Fraction<0){int segment=Math.Max(30,Width/5),x=(Environment.TickCount&Int32.MaxValue)/8%Math.Max(1,Width+segment)-segment;e.Graphics.FillRectangle(brush,x,0,segment,Height);}else e.Graphics.FillRectangle(brush,0,0,(int)(Width*Math.Max(0,Math.Min(1,Fraction))),Height);}}
}
sealed partial class LibraryForm {
    readonly Panel workPanel=new Panel{Dock=DockStyle.Bottom,Height=28,Visible=false};readonly Label workLabel=new Label{Dock=DockStyle.Top,Height=20,ForeColor=Color.LightSteelBlue};readonly WorkMeter workMeter=new WorkMeter{Dock=DockStyle.Bottom};readonly System.Windows.Forms.Timer workHeartbeat=new System.Windows.Forms.Timer{Interval=250};Button workCancel;DateTime workStartedUtc;string workPhase="Working",workActivityKey;bool WorkBelongsToPage {get{return workActivityKey==null||workActivityKey=="app"||workActivityKey==SelectedActivityKey;}}long workDone,workTotal,lastProgressTicks;
    internal static bool NeedsProfileCheck(Preferences before,Preferences after){return !String.IsNullOrWhiteSpace(after.Profile)&&(!String.Equals(before.Profile,after.Profile,StringComparison.OrdinalIgnoreCase)||!String.Equals(before.FeedUrl,after.FeedUrl,StringComparison.Ordinal));}
    void BuildWorkProgress(TableLayoutPanel body){var footer=new Panel{Dock=DockStyle.Fill,Margin=Padding.Empty};releaseLabel.Dock=DockStyle.Fill;var gauge=new Panel{Dock=DockStyle.Fill};gauge.Controls.Add(workLabel);gauge.Controls.Add(workMeter);workCancel=Button("Cancel",delegate{if(cancellation!=null&&!transaction)cancellation.Cancel();});workCancel.Dock=DockStyle.Right;workCancel.MinimumSize=new Size(86,26);workCancel.Width=86;workPanel.Controls.Add(gauge);workPanel.Controls.Add(workCancel);workHeartbeat.Tick+=delegate{if(busy)UpdateWorkProgress();else workHeartbeat.Stop();};Disposed+=delegate{workHeartbeat.Dispose();};footer.Controls.Add(releaseLabel);footer.Controls.Add(workPanel);body.Controls.Add(footer,0,3);}
    void UpdateWorkProgress(){bool shown=busy&&WorkBelongsToPage;workPanel.Visible=shown;workHeartbeat.Enabled=busy;if(workCancel!=null){workCancel.Visible=busy&&cancellation!=null&&!transaction;workCancel.Enabled=workCancel.Visible&&!cancellation.IsCancellationRequested;}if(gameBody!=null)gameBody.RowStyles[3].Height=shown?58:28;workMeter.Fraction=workTotal>0?(double)workDone/workTotal:-1;workMeter.Invalidate();workLabel.Text=(workActivityKey=="app"?"Astera: ":"")+workPhase+(workTotal>0?" · "+((double)workDone/workTotal*100).ToString("0")+"% · "+(workPhase=="Installing"?workDone+" / "+workTotal+" files":(workDone/1048576D).ToString("0.0")+" / "+(workTotal/1048576D).ToString("0.0")+" MiB"):" · "+(DateTime.UtcNow-workStartedUtc).ToString(@"mm\:ss")+" elapsed");}
    void ReportWorkProgress(string phase,long done,long total){if(IsDisposed||Disposing)return;long now=DateTime.UtcNow.Ticks;if(done>0&&done<total&&now-Interlocked.Read(ref lastProgressTicks)<TimeSpan.TicksPerMillisecond*200)return;Interlocked.Exchange(ref lastProgressTicks,now);if(InvokeRequired){try{BeginInvoke(new Action<string,long,long>(SetWorkProgress),phase,done,total);}catch(InvalidOperationException){}return;}SetWorkProgress(phase,done,total);}
    void SetWorkProgress(string phase,long done,long total){if(IsDisposed||Disposing)return;workPhase=phase;workDone=done;workTotal=total;UpdateWorkProgress();}
}
}
